from pathlib import Path
import base64, gzip, re, subprocess, tempfile

DATA = '''[... ELLIPSIZATION ...]'''

html = gzip.decompress(base64.b64decode(DATA)).decode('utf-8')
required = [
    'const LOCAL_PREVIEW=false;',
    '/api/plans',
    'CRIAR CRONOGRAMA GRÁTIS',
    'Mapa de matérias e conteúdos',
    'Cronograma de execução',
    'Continue visualizando este cronograma gratuitamente',
    'Você está estudando para:',
    'value="Outro"',
    'Poderia me enviar o código gratuito de acesso?',
    'PREVIEW_MS=60000',
]
for item in required:
    assert item in html, item
assert html.index('Mapa de matérias e conteúdos') < html.index('Cronograma de execução')
assert 'TESTAR CAPTURA' not in html
assert 'PRÉVIA LOCAL · nenhuma alteração foi publicada' not in html
Path('plano.html').write_text(html, encoding='utf-8')

scripts = re.findall(r'<script(?:[^>]*)>(.*?)</script>', html, re.S)
main = max(scripts, key=len)
with tempfile.NamedTemporaryFile('w', suffix='.js', encoding='utf-8', delete=False) as fh:
    fh.write(main)
    js_path = fh.name
subprocess.run(['node', '--check', js_path], check=True)
print('plano.html aprovado aplicado e JavaScript validado')
